import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.Bx7X8BVG.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"CF Tunnel Manager","text":"Docker 与桌面端的隧道管理面板","tagline":"v1.8.2 · Windows x64 / macOS Apple Silicon / Linux amd64 · 内置本地运行资源","image":{"src":"/logo.svg","alt":"CF Tunnel Manager"},"actions":[{"theme":"brand","text":"选择版本与快速开始","link":"/guide/"},{"theme":"alt","text":"下载桌面端","link":"/guide/desktop"},{"theme":"alt","text":"免费版限制与实际验证","link":"/guide/limits"}]},"features":[{"title":"Docker 版","details":"适合 Linux 服务器和 NAS 持续运行。通过浏览器管理，数据保存在宿主机挂载目录。"},{"title":"桌面版","details":"内置 Node、cloudflared 和生产依赖，无需 Docker。程序启动本地服务后打开管理界面。"},{"title":"多隧道管理","details":"创建隧道、配置域名路由、独立连接与断开，支持多条隧道同时在线。"},{"title":"数据留在本机","details":"用户、凭据和隧道配置持久化到本机。不同设备的数据不会自动同步，升级前请备份。"},{"title":"清楚的更新方式","details":"Docker 使用原安装目录升级；桌面端下载新版安装包覆盖安装，不使用 Git 面板更新。"},{"title":"来源与测试证据","details":"公开 Cloudflare 官方限制、安装包架构和 CI 验证范围，不把编译成功等同于公网隧道已验证。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1791444273000}'),n={name:"index.md"};function l(o,e,i,s,u,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h2 id="当前发行版本" tabindex="-1">当前发行版本 <a class="header-anchor" href="#当前发行版本" aria-label="Permalink to &quot;当前发行版本&quot;">​</a></h2><p><strong>v1.8.2</strong>，资料核对日期：<strong>2026-10-07</strong>。<a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/tag/v1.8.2" target="_blank" rel="noreferrer">Release 与下载</a>。</p><table tabindex="0"><thead><tr><th>版本</th><th>使用场景</th><th>入口</th></tr></thead><tbody><tr><td>Docker</td><td>Linux 服务器、NAS，适合长期在线</td><td><a href="/cloudflare-tunnel-manager/guide/docker">Docker 安装教程</a></td></tr><tr><td>Windows 桌面</td><td>Windows x64，本机运行服务</td><td><a href="/cloudflare-tunnel-manager/guide/desktop">桌面端安装教程</a></td></tr><tr><td>macOS 桌面</td><td>Apple Silicon（M 系列芯片）</td><td><a href="/cloudflare-tunnel-manager/guide/desktop#下载与适用系统">架构与下载</a></td></tr><tr><td>Linux 桌面</td><td>amd64 的 Debian/Ubuntu 系发行版，deb 包</td><td><a href="/cloudflare-tunnel-manager/guide/desktop#linux">安装与依赖</a></td></tr></tbody></table><p>当前 Release <strong>没有</strong> macOS Intel、Windows ARM64、Linux ARM 桌面安装包，也没有 v1.8.2 AppImage。ARM NAS 请查看 Docker 教程的架构说明。</p><h2 id="先确认你的服务在哪台设备" tabindex="-1">先确认你的服务在哪台设备 <a class="header-anchor" href="#先确认你的服务在哪台设备" aria-label="Permalink to &quot;先确认你的服务在哪台设备&quot;">​</a></h2><p>Tunnel 将访问转发到运行 <code>cloudflared</code> 的设备可达的服务。桌面端填写 <code>http://127.0.0.1:8080</code>，指的是<strong>这台电脑</strong>的 8080 端口；Docker 默认 host 网络下指的是<strong>服务器宿主机</strong>。</p><p>本项目负责连接和转发，<strong>不会自动安装或启动你要转发的网站、数据库、NAS 应用或其他业务服务</strong>。请先在本机/局域网打开业务地址，确认服务可用。</p><p>开始使用：<a href="/cloudflare-tunnel-manager/guide/">选择版本</a> → <a href="/cloudflare-tunnel-manager/get-credentials">获取凭据</a> → <a href="/cloudflare-tunnel-manager/guide/#创建第一条隧道">创建第一条隧道</a>。</p>',8)])])}const p=t(n,[["render",l]]);export{h as __pageData,p as default};
